settings.sectionCSS:
.YVrMNb-next a {
	line-height: 2;
	color: [[${globalDesignMode ? 'var(--colorBody)' : colorBody}]];
	overflow: hidden;
}

.YVrMNb-next a:hover {
	color: [[${globalDesignMode ? 'var(--colorLinkHover)' : colorLinkHover}]];
}

.YVrMNb-next:not(.previous) {
	text-align: right;
}

.YVrMNb-next:not(.previous) a:before {
	float: right;
}

.YVrMNb .has-sidebar {
	padding-right: 2.1875rem;
}

.YVrMNb-detail-time {
	margin-bottom: 1.25rem;
}

.YVrMNb-detail-time i {
	vertical-align: middle;
}

.YVrMNb-detail-share {
	margin-bottom: 1.25rem;
	display: flex;
}

.YVrMNb-detail-summary {
	text-overflow: ellipsis;
	line-clamp: 3;
	display: -webkit-box;
	-webkit-line-clamp: 3;
	overflow: hidden;
	-webkit-box-orient: vertical;
}

.YVrMNb-detail-post h5 {
	font-size: [[${globalDesignMode ? 'var(--fontSizeBody)' : fontSizeBody}]];
	font-family: [[${globalDesignMode ? 'var(--typeBody)' : typeBody}]];
	color: [[${globalDesignMode ? 'var(--colorBody)' : colorBody}]];
	overflow: hidden;
	text-overflow: ellipsis;
	display: -webkit-box;
	line-clamp: 3;
	-webkit-line-clamp: 3;
	-webkit-box-orient: vertical;
}

.YVrMNb-detail-post .embed-responsive {
	margin-right: 0.625rem;
	width: 5rem;
}

.YVrMNb-detail-post .embed-responsive img {
	border-radius: [[${globalDesignMode ? 'var(--cardBorderRadius)' : cardBorderRadius}]];
}

.YVrMNb-detail-post:not(:last-child) {
	border-bottom: [[${globalDesignMode ? 'calc(var(--borderWidth) * 1px)' : borderWidth + 'px'}]] [[${globalDesignMode ? 'var(--borderStyle)' : borderStyle}]] [[${globalDesignMode ? 'var(--colorBorder)' : colorBorder}]];
	margin-bottom: 0.9375rem;
	padding-bottom: 0.9375rem;
}

.YVrMNb-detail-post:hover h5 {
	color: [[${globalDesignMode ? 'var(--colorTheme)' : colorTheme}]];
}

.YVrMNb .section-rich-text,
.YVrMNb .section-rich-text * {
	line-height: 1.6;
}

.YVrMNb .section-rich-text + .YVrMNb-next {
	margin-top: 1.5rem;
}

.YVrMNb .slick-slider-thumbnail {
	margin-top: 1rem;
}

.YVrMNb .section-slide-round .slick-slider {
	margin-left: -15px;
	margin-right: -15px;
}

.YVrMNb .section-slide-round .slick-slider .slick-track {
	align-items: stretch;
	display: flex;
}

.YVrMNb .section-slide-round .slick-slider .slick-slide {
	margin-right: 15px;
	margin-left: 15px;
	padding-bottom: 15px;
}

@media (max-width: 768px) {
	.YVrMNb .section-slide-round .slick-slider {
		margin-left: -7.5px;
		margin-right: -7.5px;
	}

	.YVrMNb .section-slide-round .slick-slider .slick-slide {
		margin-right: 7.5px;
		margin-left: 7.5px;
	}
}

.YVrMNb-list .embed-responsive {
	width: 9.375rem;
	margin-right: 0.9375rem;
}

@media (max-width: 768px) {
	.YVrMNb-detail-share {
		display: block;
	}

	.YVrMNb-detail-share .btn {
		margin-top: 0.75rem;
	}

	.YVrMNb .col-md-8 {
		padding-left: 15px !important;
		padding-right: 15px !important;
	}
}
